create table if not exists conversations (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, customer_id uuid references customers(id), lead_name text, lead_phone text, lead_email text, channel text not null default 'internal', status text not null default 'open', assigned_user_id uuid, subject text, last_message_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists messages (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, conversation_id uuid not null references conversations(id) on delete cascade, sender_type text not null, sender_user_id uuid, content text not null, message_type text not null default 'text', created_at timestamptz not null default now());
create table if not exists opportunities (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, customer_id uuid references customers(id), conversation_id uuid references conversations(id), title text not null, description text, value numeric(14,2) not null default 0, stage text not null default 'new', assigned_user_id uuid, source text, expected_close_date date, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists automations (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, name text not null, active boolean not null default true, trigger_type text not null, conditions jsonb not null default '{}', actions jsonb not null default '[]', created_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists automation_runs (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, automation_id uuid not null references automations(id) on delete cascade, status text not null, trigger_data jsonb, result jsonb, error_message text, idempotency_key text, created_at timestamptz not null default now(), unique(automation_id, idempotency_key));
create table if not exists intelligence_insights (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, type text not null, severity text not null default 'info', title text not null, description text not null, entity text, entity_id uuid, data jsonb not null default '{}', status text not null default 'open', created_at timestamptz not null default now(), resolved_at timestamptz);
do $$ declare t text; begin foreach t in array array['conversations','messages','opportunities','automations','automation_runs','intelligence_insights'] loop execute format('alter table %I enable row level security', t); execute format('create policy company_isolation on %I for all using (is_company_member(company_id)) with check (is_company_member(company_id))', t); execute format('grant select, insert, update, delete on table %I to authenticated', t); end loop; end $$;
